import { realpathSync } from "node:fs";
import { mkdir, readFile, stat, writeFile } from "node:fs/promises";
import { resolve } from "node:path";
import type { AgentToolResult, ExtensionAPI, ExtensionContext, ToolResultEvent } from "@earendil-works/pi-coding-agent";
import { Text } from "@earendil-works/pi-tui";
import { Type } from "typebox";
import {
	DEFAULT_CONFIG,
	mergeConfig,
	type PiRulesConfig,
	type PiRulesMode,
	readConfigFromEnv,
	readConfigFromFiles,
} from "../app/config.js";
import { addSessionHotPaths, type RuntimeState, resetTurnState } from "../app/state.js";
import { formatRuleContext } from "../domain/formatter.js";
import type { MatchedRule } from "../domain/types.js";
import {
	extractPromptPaths,
	extractRemovedPaths,
	extractToolPaths,
	extractWriteToolCallPaths,
} from "../features/tool-paths.js";
import { startWatcher, type Watcher } from "../features/watcher.js";
import { findProjectRoot, normalizePath } from "../shared/path.js";
import { type AppliedRulesEntryData, renderAppliedRulesLines, statusLineText } from "./banner.js";
import { registerCommands } from "./commands.js";
import { createRuntime, normalizeCandidatePath, type RuntimeDeps } from "./runtime.js";

/** Custom chat entry type: dim "rules applied" annotation for the current turn. */
const APPLIED_RULES_ENTRY = "pi-rules-applied";

const CODE_EDIT_KEYWORDS = [
	"fix",
	"bug",
	"error",
	"implement",
	"refactor",
	"rename",
	"move",
	"delete",
	"create",
	"add",
	"remove",
	"update",
	"change",
	"modify",
	"edit",
	"write",
	"test",
	"deploy",
	"build",
	"lint",
	"format",
	"commit",
	"push",
	"merge",
	"review",
	"check",
	"debug",
	"trace",
	"investigate",
	"optimize",
	"src/",
	"test/",
	"lib/",
	"app/",
	"pages/",
	"components/",
];

function isCodeRelatedPrompt(prompt: string): boolean {
	if (prompt.trim().length === 0) return true; // empty prompt = continuation, don't filter
	const lower = prompt.toLowerCase();
	return CODE_EDIT_KEYWORDS.some((kw) => lower.includes(kw));
}

function formatMatches(matches: MatchedRule[], runtimeDeps: RuntimeDeps): string {
	return formatRuleContext(matches, runtimeDeps.engine.formatOptions).prompt;
}

export default function piRulesExtension(pi: ExtensionAPI): void {
	registerFlags(pi);

	let runtime = createRuntime(
		process.cwd(),
		mergeConfig(readConfigFromFiles(findProjectRoot(process.cwd())), readConfigFromEnv(), readFlags(pi)),
	);
	let watcher: Watcher | null = null;
	let reloadInFlight = false;
	/** Rule IDs already shown in the current agent run's applied-rules hint. */
	const annotatedRuleIds = new Set<string>();
	/**
	 * `before_agent_start` runs before Pi emits `agent_start`. Keep this scope
	 * active through that event so the static annotation is not immediately
	 * forgotten before dynamic tool-result annotations arrive.
	 */
	let appliedRulesScopeActive = false;
	/**
	 * Set when `before_agent_start` performed a static injection. The applied-rules
	 * annotation is NOT appended inline there: Pi renders the user's new message
	 * only after `before_agent_start` returns, so appending inline would place the
	 * annotation ABOVE the message. The first `context` event of the turn is the
	 * earliest point at which the message is already on screen and persisted, so
	 * the annotation is flushed there instead.
	 */
	let pendingStaticAnnotation = false;
	function syncRuntime(cwd: string): void {
		const nextProjectRoot = findProjectRoot(cwd);
		const nextConfig = mergeConfig(readConfigFromFiles(nextProjectRoot), readConfigFromEnv(), readFlags(pi));
		const projectChanged = nextProjectRoot !== runtime.state.projectRoot;
		const limitsChanged =
			nextConfig.maxRuleChars !== runtime.config.maxRuleChars ||
			nextConfig.maxContextChars !== runtime.config.maxContextChars;

		if (projectChanged || limitsChanged) {
			const previousState = runtime.state;
			annotatedRuleIds.clear();
			appliedRulesScopeActive = false;
			pendingStaticAnnotation = false;
			runtime = createRuntime(cwd, nextConfig);
			for (const path of previousState.recentReadPaths) runtime.state.recentReadPaths.add(path);
			for (const path of previousState.recentChangedPaths) runtime.state.recentChangedPaths.add(path);
			runtime.state.lastContext = previousState.lastContext;
			runtime.state.gitStatusBeforeTurn = previousState.gitStatusBeforeTurn;
			return;
		}

		runtime.config = nextConfig;
	}

	registerCommands(pi, {
		getRuntime: () => runtime,
		syncRuntime,
		updateWidget,
	});

	pi.on("session_start", async (_event, ctx) => {
		annotatedRuleIds.clear();
		appliedRulesScopeActive = false;
		pendingStaticAnnotation = false;
		const projectRoot = findProjectRoot(ctx.cwd);
		runtime = createRuntime(ctx.cwd, mergeConfig(readConfigFromFiles(projectRoot), readConfigFromEnv(), readFlags(pi)));
		await runtime.store.initialize();
		// Use loadRules with forceReload=true at startup to populate cache
		await runtime.engine.loadRules(ctx.cwd, true);
		await updateWidget(ctx);

		// Start file watcher for hot reload
		const rulesDir = resolve(runtime.state.projectRoot, ".pi/rules");
		let roots: string[] = [];
		try {
			await stat(rulesDir);
			roots = [rulesDir];
		} catch {
			// rules dir doesn't exist yet — nothing to watch
		}
		if (roots.length > 0) {
			watcher = startWatcher({
				roots,
				onChange: () => {
					if (reloadInFlight) return;
					reloadInFlight = true;
					runtime.engine.loadRules(ctx.cwd, true).finally(() => {
						reloadInFlight = false;
					});
				},
				debounceMs: 100,
			});
		}
	});

	pi.on("session_compact", async (_event, ctx) => {
		syncRuntime(ctx.cwd);
		runtime.engine.clearCache();
		resetTurnState(runtime.state);
		await updateWidget(ctx);
	});

	pi.on("agent_start", async (_event, ctx) => {
		syncRuntime(ctx.cwd);
		// The initial agent_start follows before_agent_start, so preserve the
		// static rules already shown. A direct/continuation start with no active
		// scope begins with a fresh display set.
		if (!appliedRulesScopeActive) {
			annotatedRuleIds.clear();
		}
		runtime.engine.resetTurn();
		resetTurnState(runtime.state);
	});

	pi.on("agent_settled", async () => {
		// `agent_end` can be followed by an automatic retry/continuation. Wait
		// for the settled event so those continuations share one display scope.
		annotatedRuleIds.clear();
		appliedRulesScopeActive = false;
		// A run may end without ever reaching `context` (e.g. aborted before the
		// first LLM call). Drop the pending annotation so a later turn without
		// its own injection cannot flush a stale one.
		pendingStaticAnnotation = false;
	});

	pi.on("before_agent_start", async (event, ctx) => {
		syncRuntime(ctx.cwd);
		// A new user prompt starts a new display scope. We intentionally reset
		// here rather than in agent_start because Pi emits agent_start after this
		// hook has already performed the static injection.
		annotatedRuleIds.clear();
		appliedRulesScopeActive = true;
		pendingStaticAnnotation = false;
		if (runtime.config.disabled || runtime.config.mode === "off" || runtime.config.mode === "dynamic") {
			return undefined;
		}

		const prompt = event.prompt ?? "";
		const codeRelated = isCodeRelatedPrompt(prompt);

		// Build set of context file real paths to detect AGENTS.md / CLAUDE.md overlap
		const contextFileRealPaths = new Set<string>();
		for (const contextFile of event.systemPromptOptions.contextFiles ?? []) {
			contextFileRealPaths.add(contextFile.path);
			try {
				contextFileRealPaths.add(realpathSync.native(contextFile.path));
			} catch {
				// ignore
			}
		}

		const promptPaths = extractPromptPaths(prompt)
			.map(normalizeCandidatePath)
			.filter((path): path is string => path !== undefined);
		const baseTargets = dedupePaths([
			...runtime.state.recentReadPaths,
			...runtime.state.recentChangedPaths,
			...runtime.state.sessionHotPaths,
			...promptPaths,
		]);
		// Fallback: if the current turn has no path signals (e.g. right after
		// `session_compact` when the model has lost its working-set memory),
		// reuse the target paths from the last successful injection so the
		// previously relevant rules keep applying.
		const usingLastContextFallback =
			baseTargets.length === 0 && (runtime.state.lastContext?.targetPaths?.length ?? 0) > 0;
		const targetPaths =
			baseTargets.length > 0 ? baseTargets : dedupePaths(runtime.state.lastContext?.targetPaths ?? []);

		const matchStart = performance.now();
		// Use matchRulesForPathsStatic to skip context-file-backed rules
		const context = await runtime.engine.matchRulesForPathsStatic(
			ctx.cwd,
			targetPaths,
			contextFileRealPaths,
			codeRelated ? prompt : undefined,
		);
		const matchElapsedMs = performance.now() - matchStart;

		// For non-code prompts (but not when using lastContext fallback), filter out non-alwaysApply rules
		let filteredMatches = context.matches;
		if (!codeRelated && !usingLastContextFallback) {
			filteredMatches = context.matches.filter((m) => m.matchReason.type === "alwaysApply");
		}
		// Suppress alwaysApply rules that opted into path-based suppression via
		// ignorePath when the turn carries ZERO path signals and the prompt is
		// not code-related (e.g. "fix typos in the documentation" without a file
		// path). With no targets the matcher cannot evaluate ignorePath, so we
		// apply the rule author's intent directly. Covers both the fresh-session
		// case (empty targetPaths) and the lastContext fallback (stale paths).
		if (!codeRelated && baseTargets.length === 0) {
			filteredMatches = filteredMatches.filter(
				(m) => !(m.matchReason.type === "alwaysApply" && m.frontmatter.ignorePath !== undefined),
			);
		}

		if (filteredMatches.length === 0) {
			return undefined;
		}

		// Re-format if we filtered matches
		const finalContext =
			filteredMatches.length !== context.matches.length
				? { ...context, matches: filteredMatches, prompt: formatMatches(filteredMatches, runtime) }
				: context;

		runtime.engine.markStaticInjectedBatch(finalContext.matches);
		runtime.state.lastContext = runtime.engine.recordInjection(targetPaths, finalContext, matchElapsedMs);
		await updateWidget(ctx);
		// Do not append the applied-rules annotation here. `before_agent_start`
		// runs before Pi renders the user's new message, so an inline append
		// would place the annotation ABOVE the message. Flush it on the first
		// `context` event of the turn instead, when the message is on screen and
		// persisted but the assistant has not started streaming.
		pendingStaticAnnotation = true;
		return {
			systemPrompt: `${event.systemPrompt}\n\n${finalContext.prompt}`,
		};
	});

	pi.on("context", async () => {
		if (!pendingStaticAnnotation) {
			return;
		}
		pendingStaticAnnotation = false;
		annotateAppliedRules();
	});

	pi.on("tool_call", async (event, ctx) => {
		syncRuntime(ctx.cwd);
		if (runtime.config.disabled || runtime.config.mode === "off" || !runtime.config.writeGuardEnabled) {
			return undefined;
		}

		const targetPaths = extractWriteToolCallPaths(event, runtime.state.projectRoot);
		if (targetPaths.length === 0) {
			return undefined;
		}

		const matchStart = performance.now();
		const context = await runtime.engine.matchRulesForPaths(ctx.cwd, targetPaths);
		const matchElapsedMs = performance.now() - matchStart;
		const missingGuardedRules = context.matches.filter(
			(match) => match.frontmatter.guard === true && !runtime.engine.wasFullInjected(match),
		);
		if (missingGuardedRules.length === 0) {
			return undefined;
		}

		const prompt = formatMatches(missingGuardedRules, runtime);
		runtime.engine.markStaticInjectedBatch(missingGuardedRules);
		runtime.state.lastContext = runtime.engine.recordInjection(
			targetPaths,
			{
				...context,
				matches: missingGuardedRules,
				prompt,
			},
			matchElapsedMs,
		);
		await updateWidget(ctx);
		annotateAppliedRules();

		return {
			block: true,
			reason: [
				"Blocked by pi-rules write guard.",
				"These guarded rules apply before editing the target file(s). Read them, adjust the patch, then retry the tool call.",
				"",
				prompt,
			].join("\n"),
		};
	});

	pi.on("tool_result", async (event, ctx) => {
		if (event.isError) {
			return undefined;
		}
		syncRuntime(ctx.cwd);
		const extractedPaths = extractToolPaths(event, runtime.state.projectRoot);
		trackToolPaths(runtime.state, event, extractedPaths);

		if (
			runtime.config.disabled ||
			runtime.config.mode === "off" ||
			runtime.config.mode === "static" ||
			runtime.config.dynamicInjection === "off"
		) {
			return undefined;
		}
		if (extractedPaths.length === 0) {
			return undefined;
		}

		// Use matchRulesForPathsDynamic to avoid re-injecting rules already injected this turn
		const matchStart = performance.now();
		const context = await runtime.engine.matchRulesForPathsDynamic(ctx.cwd, extractedPaths);
		const matchElapsedMs = performance.now() - matchStart;
		if (context.prompt.length === 0) {
			return undefined;
		}

		runtime.engine.markDynamicInjectedBatch(extractedPaths[0] ?? "_all", context.matches);
		runtime.state.lastContext = runtime.engine.recordInjection(extractedPaths, context, matchElapsedMs);
		await updateWidget(ctx);
		annotateAppliedRules();
		return {
			content: [...event.content, { type: "text", text: context.prompt }],
		};
	});

	pi.on("session_shutdown", async (_event, _ctx) => {
		if (watcher !== null) {
			await watcher.stop();
			watcher = null;
		}
		reloadInFlight = false;
	});

	// ─── Tools ──────────────────────────────────────

	pi.registerTool({
		name: "pi_rules_recommend",
		label: "Recommend Rule Update",
		description:
			"Recommend that a .pi/rules file should be updated to document a convention, pattern, or architecture decision. Call this when you've identified a convention that should be documented after writing code — the user will review and approve the update later.",
		promptSnippet: "Recommend updating a .pi/rules file when you identify a convention worth documenting",
		promptGuidelines: [
			"After implementing a pattern or convention, use pi_rules_recommend to suggest documenting it in the relevant .pi/rules file.",
			"Provide clear, specific content describing what should be added or changed in the rule.",
			"Set rulePath to the matching .pi/rules file (or leave empty if a new rule is needed).",
			"Do NOT call this for trivial changes — only for meaningful conventions worth documenting.",
		],
		parameters: Type.Object({
			rulePath: Type.String({
				description:
					"Relative path to the .pi/rules file to update (e.g. 'architecture/api-routing.md'). Leave empty if a new rule file may be needed.",
			}),
			summary: Type.String({
				description: "Short one-line summary of the recommendation (shown in /pi-rules:status list).",
			}),
			content: Type.String({
				description:
					"The specific content to add or change in the rule. Be precise — this is what the maintainer agent will write. Include markdown formatting if needed.",
			}),
			reason: Type.String({
				description: "Why this rule update is needed. What convention or pattern was introduced?",
			}),
		}),
		async execute(_toolCallId, params, _signal, _onUpdate, ctx): Promise<AgentToolResult<{ id: string }>> {
			syncRuntime(ctx.cwd);

			// Build the absolute rule path
			let ruleAbsPath: string;
			let ruleRelativePath: string;
			if (params.rulePath && params.rulePath.length > 0) {
				ruleAbsPath = resolve(runtime.state.projectRoot, ".pi/rules", params.rulePath);
				ruleRelativePath = normalizePath(`.pi/rules/${params.rulePath}`);
			} else {
				ruleAbsPath = resolve(runtime.state.projectRoot, ".pi/rules", "(to be determined)");
				ruleRelativePath = ".pi/rules/(to be determined)";
			}

			await runtime.store.initialize();
			const rec = await runtime.store.create({
				rulePath: ruleAbsPath,
				ruleRelativePath,
				summary: params.summary,
				content: params.content,
				reason: params.reason,
				status: "pending",
			});

			return {
				content: [
					{
						type: "text",
						text: `Recommendation ${rec.id} created for ${ruleRelativePath}. Review and apply it through the pi-rules TUI.`,
					},
				],
				details: { id: rec.id },
			};
		},
	});

	pi.registerTool({
		name: "create_rule",
		label: "Create Rule",
		description: "Create a new .pi/rules markdown file with frontmatter",
		promptSnippet: "Create durable .pi/rules files when the user asks to persist a project convention.",
		promptGuidelines: [
			"Use create_rule when the user explicitly wants to save an instruction under .pi/rules.",
			"When creating an alwaysApply rule, always consider adding ignorePath for non-code areas (e.g. docs/**) so the rule is not injected while the agent works on documentation — this saves tokens.",
		],
		parameters: Type.Object({
			name: Type.String({ description: "Safe filename stem for the rule" }),
			summary: Type.String({ description: "One-line routing summary" }),
			paths: Type.Array(Type.String({ description: "Project-relative glob pattern" }), {
				description: "Project-relative path scopes for the rule",
			}),
			body: Type.String({ description: "Markdown rule body" }),
			alwaysApply: Type.Optional(Type.Boolean({ description: "Apply to all turns" })),
			ignorePath: Type.Optional(
				Type.Array(Type.String({ description: "Project-relative glob pattern to exclude" }), {
					description: "Paths where the rule should NOT apply (e.g. docs/** for alwaysApply rules)",
				}),
			),
			overwrite: Type.Optional(Type.Boolean({ description: "Overwrite if the file already exists" })),
		}),
		async execute(_toolCallId, params, _signal, _onUpdate, ctx): Promise<AgentToolResult<{ path: string }>> {
			syncRuntime(ctx.cwd);
			const fileName = sanitizeRuleName(params.name);
			const rulePath = resolve(runtime.state.projectRoot, ".pi/rules", `${fileName}.md`);
			const existing = await readFile(rulePath, "utf8").catch(() => undefined);
			if (existing !== undefined && params.overwrite !== true) {
				return {
					content: [{ type: "text", text: `Rule already exists at ${rulePath}. Re-run with overwrite=true.` }],
					details: { path: rulePath },
				};
			}

			const frontmatterLines = [
				"---",
				"paths:",
				...params.paths.map((path) => `  - ${JSON.stringify(path)}`),
				...(params.ignorePath && params.ignorePath.length > 0
					? ["ignorePath:", ...params.ignorePath.map((path) => `  - ${JSON.stringify(path)}`)]
					: []),
				`summary: ${JSON.stringify(params.summary)}`,
				`alwaysApply: ${params.alwaysApply === true ? "true" : "false"}`,
				"---",
				"",
			];
			await mkdir(resolve(runtime.state.projectRoot, ".pi/rules"), { recursive: true });
			await writeFile(rulePath, `${frontmatterLines.join("\n")}${params.body.trim()}\n`, "utf8");
			runtime.engine.clearCache();
			await runtime.engine.loadRules(runtime.state.projectRoot, true);
			return {
				content: [{ type: "text", text: `Created rule at ${rulePath}` }],
				details: { path: rulePath },
			};
		},
	});

	// ─── Status widget ────────────────────────────────

	async function updateWidget(ctx: ExtensionContext): Promise<void> {
		if (!runtime.config.widgetEnabled) {
			ctx.ui.setStatus("pi-rules", undefined);
			return;
		}

		const status = await runtime.engine.getStatus(ctx.cwd).catch(() => undefined);
		const ruleCount = status?.ruleCount ?? 0;
		const hasErrors = status?.diagnostics.some((diagnostic) => diagnostic.severity === "error") ?? false;

		const stats = await runtime.store.getStats().catch(() => ({ pending: 0 }));
		ctx.ui.setStatus("pi-rules", statusLineText({ ruleCount, hasErrors, pendingCount: stats.pending ?? 0 }));
	}

	/**
	 * Append a dim chat-transcript annotation listing newly injected rules in
	 * the current agent run. TUI-only (custom entry, never sent to the LLM).
	 *
	 * The static `before_agent_start` injection is flushed here from the first
	 * `context` event (see `pendingStaticAnnotation`) so the annotation lands
	 * below the user's new message; write-guard and tool-result injections
	 * call this inline mid-turn.
	 */
	function annotateAppliedRules(): void {
		if (!runtime.config.appliedWidgetEnabled) {
			return;
		}
		const lastContext = runtime.engine.getLastContext();
		if (lastContext === undefined || lastContext.rules.length === 0) {
			return;
		}

		// Dynamic injections can rediscover the same rule for every target path,
		// and static + dynamic mode can see it more than once in one agent run.
		// Append only rules that have not already appeared in this run; keep the
		// first match reason and incoming matcher order.
		const newRules = lastContext.rules.filter((rule) => {
			if (annotatedRuleIds.has(rule.ruleId)) return false;
			annotatedRuleIds.add(rule.ruleId);
			return true;
		});
		if (newRules.length === 0) {
			return;
		}

		pi.appendEntry(APPLIED_RULES_ENTRY, {
			rules: newRules.map((rule) => ({
				ruleId: rule.ruleId,
				relativePath: rule.relativePath,
				summary: rule.summary,
				matchReason: rule.matchReason,
			})),
		} satisfies AppliedRulesEntryData);
	}

	// Dim annotation in the chat transcript listing the rules applied to the
	// current turn. Rendered as dim tree lines; not part of LLM context.
	pi.registerEntryRenderer(APPLIED_RULES_ENTRY, (entry, _options, theme) => {
		const lines = renderAppliedRulesLines(entry.data as AppliedRulesEntryData, (token, text) => theme.fg(token, text));
		// Explicit zero padding: the Text default (1, 1) would add a blank line
		// and a leading space, breaking the flush-under-tool-call layout.
		return new Text(lines.join("\n"), 0, 0);
	});
}

function registerFlags(pi: ExtensionAPI): void {
	pi.registerFlag("pi-rules-disabled", {
		description: "Disable pi-rules injection and maintenance",
		type: "boolean",
		default: false,
	});
	pi.registerFlag("pi-rules-mode", {
		description: "pi-rules mode: static, dynamic, both, or off",
		type: "string",
		default: "both",
	});
	pi.registerFlag("pi-rules-recommendations", {
		description: "Enable pi-rules recommendations",
		type: "boolean",
		default: true,
	});
	pi.registerFlag("pi-rules-widget", {
		description: "Enable pi-rules status widget",
		type: "boolean",
		default: true,
	});
	pi.registerFlag("pi-rules-applied-widget", {
		description: "Append a dim chat annotation listing the rules applied to the current turn",
		type: "boolean",
		default: true,
	});
	pi.registerFlag("pi-rules-write-guard", {
		description: "Block write/edit tool calls until matching guarded rules have been injected",
		type: "boolean",
		default: false,
	});
	pi.registerFlag("pi-rules-dynamic-injection", {
		description: "Dynamic rule injection after tool results: full or off",
		type: "string",
		default: "full",
	});
}

function readFlags(pi: ExtensionAPI): Partial<PiRulesConfig> {
	const mode = pi.getFlag("pi-rules-mode");
	const dynamicInjection = pi.getFlag("pi-rules-dynamic-injection");
	return {
		disabled: pi.getFlag("pi-rules-disabled") === true ? true : undefined,
		mode: isMode(mode) && mode !== DEFAULT_CONFIG.mode ? mode : undefined,
		recommendationEnabled: pi.getFlag("pi-rules-recommendations") === false ? false : undefined,
		widgetEnabled: pi.getFlag("pi-rules-widget") === false ? false : undefined,
		appliedWidgetEnabled: pi.getFlag("pi-rules-applied-widget") === false ? false : undefined,
		writeGuardEnabled: pi.getFlag("pi-rules-write-guard") === true ? true : undefined,
		dynamicInjection:
			isDynamicInjection(dynamicInjection) && dynamicInjection !== DEFAULT_CONFIG.dynamicInjection
				? dynamicInjection
				: undefined,
	};
}

function isMode(value: unknown): value is PiRulesMode {
	return value === "static" || value === "dynamic" || value === "both" || value === "off";
}

function isDynamicInjection(value: unknown): value is PiRulesConfig["dynamicInjection"] {
	return value === "off" || value === "full";
}

function trackToolPaths(state: RuntimeState, event: ToolResultEvent, extractedPaths: string[]): void {
	for (const path of extractedPaths) {
		if (["read", "grep", "find", "ls"].includes(event.toolName)) {
			state.recentReadPaths.add(path);
		}
		if (["write", "edit", "bash"].includes(event.toolName)) {
			state.recentChangedPaths.add(path);
		}
	}
	// Track removed paths for rm commands
	if (event.toolName === "bash" && typeof event.input.command === "string") {
		const removedPaths = extractRemovedPaths(event.input.command, state.projectRoot);
		for (const path of removedPaths) {
			state.recentChangedPaths.add(path);
		}
	}
	// Augment the across-turn session memory so that rule matching survives
	// turn boundaries and `session_compact`. Cap is enforced by `addSessionHotPaths`.
	addSessionHotPaths(state, extractedPaths);
}

function dedupePaths(paths: Iterable<string>): string[] {
	return [...new Set([...paths].map((path) => normalizePath(path)).filter(Boolean))];
}

function sanitizeRuleName(name: string): string {
	const normalized = name
		.toLowerCase()
		.replace(/[^a-z0-9-]+/g, "-")
		.replace(/^-+|-+$/g, "");
	if (normalized.length === 0) {
		throw new Error("Rule name must contain at least one alphanumeric character.");
	}
	return normalized;
}
